            cost, extra = 1 + regions[stack[-1]], -regions[stack[-1]]
        if name == "HALT":
            base = stack[-1]
            if base not in regions:
                return finish("PROGRAM_ERROR", op, detail="invalid output region")
            n = memory[base]
